    'CREATE TABLE IF NOT EXISTS shop_terms (\n\tid UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\ttitle VARCHAR(255) NOT NULL, \n\tcontent TEXT NOT NULL, \n\tdisplay_order INTEGER NOT NULL, \n\tis_default_invoice BOOLEAN NOT NULL, \n\tis_default_catalog BOOLEAN NOT NULL, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE\n)',
    'CREATE TABLE IF NOT EXISTS stock_locations (\n\tid UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\tname VARCHAR(255) NOT NULL, \n\tcode VARCHAR(50), \n\tis_default BOOLEAN NOT NULL, \n\tis_active BOOLEAN NOT NULL, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE\n)',
    'CREATE TABLE IF NOT EXISTS suppliers (\n\tid UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\tname TEXT NOT NULL, \n\temail TEXT NOT NULL, \n\tphone VARCHAR(20), \n\tsupplier_type client_type NOT NULL, \n\ttax_pin VARCHAR(30), \n\trequires_etims BOOLEAN NOT NULL, \n\tpayment_terms VARCHAR(50), \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE\n)',
    'CREATE TABLE IF NOT EXISTS tax_instalments (\n\tid UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\tyear INTEGER NOT NULL, \n\tinstalment_number INTEGER NOT NULL, \n\tdue_date DATE NOT NULL, \n\testimated_amount NUMERIC(15, 2) NOT NULL, \n\tpaid_amount NUMERIC(15, 2) NOT NULL, \n\tpaid_at TIMESTAMP WITHOUT TIME ZONE, \n\tpayment_reference TEXT, \n\tstatus TEXT NOT NULL, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE\n)',
    'CREATE TABLE IF NOT EXISTS wht_payments (\n\tid UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\tmonth INTEGER NOT NULL, \n\tyear INTEGER NOT NULL, \n\tgross_amount NUMERIC(15, 2) NOT NULL, \n\twht_rate NUMERIC(5, 2) NOT NULL, \n\twht_amount NUMERIC(15, 2) NOT NULL, \n\tsource_document_id UUID, \n\tstatus TEXT NOT NULL, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE\n)',
    'CREATE TABLE IF NOT EXISTS accounting_periods (\n\tid UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\tfiscal_year_id UUID, \n\tperiod_name VARCHAR(50) NOT NULL, \n\tstart_date DATE NOT NULL, \n\tend_date DATE NOT NULL, \n\tstatus period_status NOT NULL, \n\tclosed_at TIMESTAMP WITHOUT TIME ZONE, \n\tclosed_by_id UUID, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE, \n\tFOREIGN KEY(fiscal_year_id) REFERENCES fiscal_years (id) ON DELETE SET NULL, \n\tFOREIGN KEY(closed_by_id) REFERENCES users (id) ON DELETE SET NULL\n)',
    'CREATE TABLE IF NOT EXISTS bill_of_materials (\n\tid UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\tfinished_product_id UUID NOT NULL, \n\tname VARCHAR(255) NOT NULL, \n\tlabor_cost_estimate NUMERIC(14, 2) NOT NULL, \n\toverhead_cost_estimate NUMERIC(14, 2) NOT NULL, \n\tis_active BOOLEAN NOT NULL, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE, \n\tFOREIGN KEY(finished_product_id) REFERENCES products (id)\n)',
    'CREATE TABLE IF NOT EXISTS budgets (\n\tid UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\taccount_id UUID NOT NULL, \n\tmonth INTEGER NOT NULL, \n\tyear INTEGER NOT NULL, \n\tmonthly_limit NUMERIC(15, 2) NOT NULL, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE, \n\tFOREIGN KEY(account_id) REFERENCES chart_of_accounts (id) ON DELETE CASCADE\n)',
    'CREATE TABLE IF NOT EXISTS client_loyalty_accounts (\n\tid UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\tclient_id UUID NOT NULL, \n\tmember_number VARCHAR(50), \n\ttier_id UUID, \n\tcurrent_points INTEGER NOT NULL, \n\tlifetime_points INTEGER NOT NULL, \n\twallet_balance_kes NUMERIC(12, 2) NOT NULL, \n\tmembership_status VARCHAR(20) NOT NULL, \n\texpires_at TIMESTAMP WITHOUT TIME ZONE, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tupdated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE, \n\tFOREIGN KEY(client_id) REFERENCES clients (id) ON DELETE CASCADE, \n\tFOREIGN KEY(tier_id) REFERENCES membership_tiers (id) ON DELETE SET NULL\n)',
    'CREATE TABLE IF NOT EXISTS deals (\n\tid UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\tclient_id UUID, \n\tassigned_user_id UUID, \n\ttitle VARCHAR(255) NOT NULL, \n\tcontact_name VARCHAR(255) NOT NULL, \n\tcontact_email VARCHAR(255), \n\tcontact_phone VARCHAR(50), \n\tstage deal_stage NOT NULL, \n\tcurrency VARCHAR(10) NOT NULL, \n\testimated_value NUMERIC(14, 2) NOT NULL, \n\twin_probability INTEGER NOT NULL, \n\texpected_close_date TIMESTAMP WITHOUT TIME ZONE, \n\tloss_reason TEXT, \n\tnotes TEXT, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tupdated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE, \n\tFOREIGN KEY(client_id) REFERENCES clients (id) ON DELETE SET NULL, \n\tFOREIGN KEY(assigned_user_id) REFERENCES users (id) ON DELETE SET NULL\n)',
    'CREATE TABLE IF NOT EXISTS documents (\n\tid UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\tclient_id UUID, \n\tsupplier_id UUID, \n\ttype doc_type NOT NULL, \n\tdoc_number VARCHAR(50) NOT NULL, \n\tstatus doc_status NOT NULL, \n\tkra_cu_invoice_number VARCHAR(100), \n\tparent_document_id UUID, \n\trequires_etims BOOLEAN NOT NULL, \n\tnotes TEXT, \n\tterms_and_conditions TEXT, \n\tpayment_channel VARCHAR(50), \n\tpayment_reference VARCHAR(100), \n\tattachment_url TEXT, \n\tattachment_name VARCHAR(255), \n\tattachment_size INTEGER, \n\tresend_email_id VARCHAR(100), \n\temail_delivery_status VARCHAR(50) NOT NULL, \n\tlast_email_sent_at TIMESTAMP WITHOUT TIME ZONE, \n\tlast_email_opened_at TIMESTAMP WITHOUT TIME ZONE, \n\tlast_reminder_sent_at TIMESTAMP WITHOUT TIME ZONE, \n\tis_read_by_recipient BOOLEAN NOT NULL, \n\tclient_portal_response VARCHAR(50), \n\tclient_amendment_notes TEXT, \n\tloyalty_points_earned INTEGER, \n\tloyalty_points_redeemed INTEGER, \n\tloyalty_discount_amount NUMERIC(12, 2), \n\tcurrency VARCHAR(3), \n\texchange_rate NUMERIC(12, 4) NOT NULL, \n\tbase_currency VARCHAR(3), \n\tbase_grand_total NUMERIC(12, 2), \n\tsub_total NUMERIC(12, 2) NOT NULL, \n\ttax_amount NUMERIC(12, 2) NOT NULL, \n\tgrand_total NUMERIC(12, 2) NOT NULL, \n\tissue_date TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tdue_date TIMESTAMP WITHOUT TIME ZONE, \n\tis_recurring BOOLEAN NOT NULL, \n\trecurring_interval recurring_interval, \n\tnext_recurring_date TIMESTAMP WITHOUT TIME ZONE, \n\tlocation_id UUID, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tCONSTRAINT unique_shop_doc_number UNIQUE (shop_id, doc_number, type), \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE, \n\tFOREIGN KEY(client_id) REFERENCES clients (id), \n\tFOREIGN KEY(supplier_id) REFERENCES suppliers (id)\n)',
    'CREATE TABLE IF NOT EXISTS expense_claims (\n\tid UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\temployee_id UUID NOT NULL, \n\tclaim_number VARCHAR(50) NOT NULL, \n\ttitle VARCHAR(255) NOT NULL, \n\tdescription TEXT, \n\tamount NUMERIC(14, 2) NOT NULL, \n\tclaim_date DATE NOT NULL, \n\tcategory expense_category NOT NULL, \n\tcost_center_id UUID, \n\treceipt_url TEXT, \n\tstatus expense_claim_status NOT NULL, \n\tapproved_by_id UUID, \n\tapproved_at TIMESTAMP WITHOUT TIME ZONE, \n\tapproval_notes TEXT, \n\tdisbursed_expense_id UUID, \n\tdisbursed_at TIMESTAMP WITHOUT TIME ZONE, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE, \n\tFOREIGN KEY(employee_id) REFERENCES employees (id) ON DELETE CASCADE, \n\tFOREIGN KEY(approved_by_id) REFERENCES users (id) ON DELETE SET NULL, \n\tFOREIGN KEY(disbursed_expense_id) REFERENCES expenses (id) ON DELETE SET NULL\n)',
    'CREATE TABLE IF NOT EXISTS journal_entries (\n\tid UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\tperiod_id UUID, \n\tentry_date TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tdescription TEXT NOT NULL, \n\tdebit_account_id UUID NOT NULL, \n\tcredit_account_id UUID NOT NULL, \n\tamount NUMERIC(15, 2) NOT NULL, \n\treference_number VARCHAR(100), \n\tcost_center_id UUID, \n\tsource_type journal_source NOT NULL, \n\tsource_id UUID, \n\tcreated_by_id UUID, \n\tis_backdated BOOLEAN NOT NULL, \n\tbackdated_reason TEXT, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE, \n\tFOREIGN KEY(debit_account_id) REFERENCES chart_of_accounts (id), \n\tFOREIGN KEY(credit_account_id) REFERENCES chart_of_accounts (id), \n\tFOREIGN KEY(created_by_id) REFERENCES users (id) ON DELETE SET NULL\n)',
    'CREATE TABLE IF NOT EXISTS stock_ledger (\n\tid UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\tproduct_id UUID NOT NULL, \n\tlocation_id UUID, \n\tmovement_type stock_movement_type NOT NULL, \n\tquantity NUMERIC(12, 2) NOT NULL, \n\tunit_cost NUMERIC(12, 2) NOT NULL, \n\trunning_balance NUMERIC(12, 2), \n\tsource_document_id UUID, \n\ttransfer_id UUID, \n\tadjustment_reason stock_adjustment_reason, \n\tnotes TEXT, \n\tcreated_by_id UUID, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE, \n\tFOREIGN KEY(product_id) REFERENCES products (id) ON DELETE CASCADE, \n\tFOREIGN KEY(location_id) REFERENCES stock_locations (id) ON DELETE SET NULL, \n\tFOREIGN KEY(created_by_id) REFERENCES users (id)\n)',
    'CREATE TABLE IF NOT EXISTS stocktakes (\n\tid UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\tlocation_id UUID NOT NULL, \n\tstocktake_number VARCHAR(50) NOT NULL, \n\tstatus stocktake_status NOT NULL, \n\tconducted_by_user_id UUID NOT NULL, \n\tstarted_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tcompleted_at TIMESTAMP WITHOUT TIME ZONE, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE, \n\tFOREIGN KEY(location_id) REFERENCES stock_locations (id), \n\tFOREIGN KEY(conducted_by_user_id) REFERENCES users (id)\n)',
    'CREATE TABLE IF NOT EXISTS storage_bins (\n\tid UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\tlocation_id UUID NOT NULL, \n\tzone VARCHAR(50) NOT NULL, \n\track VARCHAR(50), \n\tshelf VARCHAR(50), \n\tbin_code VARCHAR(50) NOT NULL, \n\tcapacity_volume NUMERIC(10, 2), \n\tmax_weight NUMERIC(10, 2), \n\tis_pickable BOOLEAN NOT NULL, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE, \n\tFOREIGN KEY(location_id) REFERENCES stock_locations (id) ON DELETE CASCADE\n)',
    'CREATE TABLE IF NOT EXISTS bom_items (\n\tid UUID NOT NULL, \n\tbom_id UUID NOT NULL, \n\traw_material_product_id UUID NOT NULL, \n\tquantity_required NUMERIC(12, 4) NOT NULL, \n\twastage_percentage NUMERIC(5, 2) NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(bom_id) REFERENCES bill_of_materials (id) ON DELETE CASCADE, \n\tFOREIGN KEY(raw_material_product_id) REFERENCES products (id)\n)',
    'CREATE TABLE IF NOT EXISTS contracts (\n\tid UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\tclient_id UUID, \n\tdeal_id UUID, \n\tcontract_number VARCHAR(50) NOT NULL, \n\ttitle VARCHAR(255) NOT NULL, \n\tdescription TEXT, \n\tcurrency VARCHAR(10) NOT NULL, \n\tstatus contract_status NOT NULL, \n\tmonthly_fee NUMERIC(14, 2) NOT NULL, \n\tis_retainer_hours BOOLEAN NOT NULL, \n\tmonthly_hours_allocated NUMERIC(8, 2) NOT NULL, \n\thourly_rate NUMERIC(12, 2) NOT NULL, \n\tauto_invoice_enabled BOOLEAN NOT NULL, \n\tnext_billing_date DATE, \n\tbilling_day_of_month INTEGER NOT NULL, \n\tstart_date DATE NOT NULL, \n\tend_date DATE, \n\talert_30_day_sent_at TIMESTAMP WITHOUT TIME ZONE, \n\talert_60_day_sent_at TIMESTAMP WITHOUT TIME ZONE, \n\tterms_and_conditions TEXT, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tupdated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE, \n\tFOREIGN KEY(client_id) REFERENCES clients (id) ON DELETE SET NULL, \n\tFOREIGN KEY(deal_id) REFERENCES deals (id) ON DELETE SET NULL\n)',
    'CREATE TABLE IF NOT EXISTS deal_activities (\n\tid UUID NOT NULL, \n\tdeal_id UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\tuser_id UUID, \n\tactivity_type deal_activity_type NOT NULL, \n\ttitle VARCHAR(255) NOT NULL, \n\tbody TEXT NOT NULL, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(deal_id) REFERENCES deals (id) ON DELETE CASCADE, \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE, \n\tFOREIGN KEY(user_id) REFERENCES users (id) ON DELETE SET NULL\n)',
    'CREATE TABLE IF NOT EXISTS document_items (\n\tid UUID NOT NULL, \n\tdocument_id UUID NOT NULL, \n\tproduct_id UUID, \n\tdescription TEXT NOT NULL, \n\tnotes TEXT, \n\tquantity NUMERIC(10, 2) NOT NULL, \n\tunit_price NUMERIC(12, 2) NOT NULL, \n\ttax_type tax_type NOT NULL, \n\ttax_amount NUMERIC(12, 2) NOT NULL, \n\titem_total NUMERIC(12, 2) NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE, \n\tFOREIGN KEY(product_id) REFERENCES products (id) ON DELETE SET NULL\n)',
    'CREATE TABLE IF NOT EXISTS document_notes (\n\tid UUID NOT NULL, \n\tdocument_id UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\tuser_id UUID NOT NULL, \n\tnote TEXT NOT NULL, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE, \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE, \n\tFOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE\n)',
    'CREATE TABLE IF NOT EXISTS document_payments (\n\tid UUID NOT NULL, \n\tdocument_id UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\tamount NUMERIC(12, 2) NOT NULL, \n\tpayment_date TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tpayment_channel VARCHAR(50) NOT NULL, \n\tpayment_reference VARCHAR(100), \n\tnotes TEXT, \n\trecorded_by_user_id UUID, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE, \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE, \n\tFOREIGN KEY(recorded_by_user_id) REFERENCES users (id) ON DELETE SET NULL\n)',
    'CREATE TABLE IF NOT EXISTS document_tokens (\n\tid UUID NOT NULL, \n\tdocument_id UUID NOT NULL, \n\ttoken VARCHAR(128) NOT NULL, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE\n)',
    'CREATE TABLE IF NOT EXISTS loyalty_ledger (\n\tid UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\taccount_id UUID NOT NULL, \n\tmovement_type loyalty_movement_type NOT NULL, \n\tpoints_delta INTEGER NOT NULL, \n\twallet_delta_kes NUMERIC(12, 2) NOT NULL, \n\trunning_points_balance INTEGER NOT NULL, \n\trunning_wallet_balance_kes NUMERIC(12, 2) NOT NULL, \n\tsource_document_id UUID, \n\tnotes TEXT, \n\tcreated_by_id UUID, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE, \n\tFOREIGN KEY(account_id) REFERENCES client_loyalty_accounts (id) ON DELETE CASCADE, \n\tFOREIGN KEY(source_document_id) REFERENCES documents (id) ON DELETE SET NULL, \n\tFOREIGN KEY(created_by_id) REFERENCES users (id) ON DELETE SET NULL\n)',
    'CREATE TABLE IF NOT EXISTS product_batches (\n\tid UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\tproduct_id UUID NOT NULL, \n\tlocation_id UUID NOT NULL, \n\tbin_id UUID, \n\tbatch_number VARCHAR(100) NOT NULL, \n\tmanufacture_date DATE, \n\texpiry_date DATE NOT NULL, \n\tinitial_quantity NUMERIC(12, 2) NOT NULL, \n\tcurrent_quantity NUMERIC(12, 2) NOT NULL, \n\tcost_price NUMERIC(12, 2) NOT NULL, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE, \n\tFOREIGN KEY(product_id) REFERENCES products (id) ON DELETE CASCADE, \n\tFOREIGN KEY(location_id) REFERENCES stock_locations (id), \n\tFOREIGN KEY(bin_id) REFERENCES storage_bins (id) ON DELETE SET NULL\n)',
    'CREATE TABLE IF NOT EXISTS production_orders (\n\tid UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\tbom_id UUID NOT NULL, \n\torder_number VARCHAR(50) NOT NULL, \n\ttarget_location_id UUID NOT NULL, \n\tunits_to_produce NUMERIC(12, 2) NOT NULL, \n\ttotal_cost_kes NUMERIC(14, 2) NOT NULL, \n\tstatus production_order_status NOT NULL, \n\tcompleted_at TIMESTAMP WITHOUT TIME ZONE, \n\tnotes TEXT, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE, \n\tFOREIGN KEY(bom_id) REFERENCES bill_of_materials (id), \n\tFOREIGN KEY(target_location_id) REFERENCES stock_locations (id)\n)',
    'CREATE TABLE IF NOT EXISTS proposals (\n\tid UUID NOT NULL, \n\tshop_id UUID NOT NULL, \n\tdeal_id UUID, \n\tclient_id UUID, \n\tproposal_number VARCHAR(50) NOT NULL, \n\ttitle VARCHAR(255) NOT NULL, \n\texecutive_summary TEXT, \n\tscope_of_work TEXT, \n\tterms_and_conditions TEXT, \n\tvalidity_days INTEGER NOT NULL, \n\tcurrency VARCHAR(10) NOT NULL, \n\tsubtotal NUMERIC(14, 2) NOT NULL, \n\tstatus proposal_status NOT NULL, \n\tviewed_at TIMESTAMP WITHOUT TIME ZONE, \n\tview_count INTEGER NOT NULL, \n\tresponded_at TIMESTAMP WITHOUT TIME ZONE, \n\tsigner_name VARCHAR(255), \n\tsignature_data_url TEXT, \n\tamendment_notes TEXT, \n\tconverted_document_id UUID, \n\tsent_at TIMESTAMP WITHOUT TIME ZONE, \n\texpires_at TIMESTAMP WITHOUT TIME ZONE, \n\tcreated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tupdated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(shop_id) REFERENCES shops (id) ON DELETE CASCADE, \n\tFOREIGN KEY(deal_id) REFERENCES deals (id) ON DELETE SET NULL, \n\tFOREIGN KEY(client_id) REFERENCES clients (id) ON DELETE SET NULL, \n\tFOREIGN KEY(converted_document_id) REFERENCES documents (id) ON DELETE SET NULL\n)',
    'CREATE TABLE IF NOT EXISTS stocktake_items (\n\tid UUID NOT NULL, \n\tstocktake_id UUID NOT NULL, \n\tproduct_id UUID NOT NULL, \n\tbin_id UUID, \n\tbatch_id UUID, \n\tbook_quantity NUMERIC(12, 2) NOT NULL, \n\tcounted_quantity NUMERIC(12, 2) NOT NULL, \n\tvariance_quantity NUMERIC(12, 2) NOT NULL, \n\tvariance_cost_kes NUMERIC(14, 2) NOT NULL, \n\tnotes TEXT, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(stocktake_id) REFERENCES stocktakes (id) ON DELETE CASCADE, \n\tFOREIGN KEY(product_id) REFERENCES products (id)\n)',
